import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.Dh6DF7gt.js";const i="/ai-lab-smart-office/smart-control-architecture.svg",u=JSON.parse('{"title":"智能化总体方案","description":"基于办公室平面布局的自动照明、自动窗帘、环境、空调、能耗与安全联动方案。","frontmatter":{"title":"智能化总体方案","description":"基于办公室平面布局的自动照明、自动窗帘、环境、空调、能耗与安全联动方案。"},"headers":[],"relativePath":"implementation/smart-office-plan.md","filePath":"implementation/smart-office-plan.md","lastUpdated":1785488055000}'),l={name:"implementation/smart-office-plan.md"};function o(n,t,s,h,b,g){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="智能化总体方案" tabindex="-1">智能化总体方案 <a class="header-anchor" href="#智能化总体方案" aria-label="Permalink to &quot;智能化总体方案&quot;">​</a></h1><h2 id="方案结论" tabindex="-1">方案结论 <a class="header-anchor" href="#方案结论" aria-label="Permalink to &quot;方案结论&quot;">​</a></h2><p>本项目建议采用 <strong>有线控制骨干 + 低功耗无线传感器 + 本地自动化平台</strong> 的混合架构：固定安装且影响办公连续性的灯光、窗帘和空调使用 DALI-2、KNX 或 Modbus 等有线方式；人体存在、温湿度和门磁等辅助传感器可使用 Zigbee；所有场景由机房内的 Home Assistant 统一编排。</p><p><img src="'+i+'" alt="AI实验室本地自动化控制架构"></p><p>设计目标不是“所有设备都能在手机上点”，而是做到：</p><ol><li>有人且照度不足时自动亮灯，无人后分级关闭。</li><li>窗帘根据日照、眩光、室温和会议场景自动调整。</li><li>手动开关始终可用，并在一段时间内覆盖自动规则。</li><li>平台或网络故障时，灯光、窗帘和空调仍可本地操作。</li><li>所有设备状态、告警、能耗和自动化执行结果可以追溯。</li></ol><h2 id="技术架构" tabindex="-1">技术架构 <a class="header-anchor" href="#技术架构" aria-label="Permalink to &quot;技术架构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>子系统</th><th>推荐方案</th><th>改造兼容方案</th></tr></thead><tbody><tr><td>照明</td><td>可更换驱动的灯具使用 DALI-2，按灯具或逻辑组调光</td><td>保留原灯具时，在配电箱或检修区使用有线继电器/调光模块控制回路</td></tr><tr><td>窗帘</td><td>交流管状电机或开合帘电机，控制器必须具备正反转互锁</td><td>无反馈电机可按运行时间估算位置，但验收时须校准全开/全关时间</td></tr><tr><td>传感器</td><td>开放区、会议室和餐厅采用有线存在+照度传感器</td><td>独立办公室和辅助空间可使用 Zigbee 存在、门磁和环境传感器</td></tr><tr><td>空调/新风</td><td>优先使用原厂网关、BACnet、KNX 或 Modbus 接口</td><td>没有开放接口时仅做状态监测；红外控制只用于非关键房间</td></tr><tr><td>自动化平台</td><td>机房部署 Home Assistant、MQTT、Zigbee2MQTT，接 UPS</td><td>Node-RED 仅用于复杂流程，不作为简单开关的唯一控制路径</td></tr><tr><td>网络</td><td>建议新增 VLAN 30 承载自动化服务，IoT 设备继续使用 VLAN 20</td><td>暂不新增 VLAN 时，平台可先放受控服务器区并通过防火墙访问 VLAN 20</td></tr></tbody></table><p>DALI-2 已定义按钮、存在传感器和照度传感器等输入设备；Home Assistant 可通过本地 KNX/IP 或 Modbus 接口管理灯光、窗帘、空调等实体。无线设备以 Zigbee 为主，Matter/Thread 作为后续兼容方向，不作为第一阶段固定回路的唯一控制方式。</p><h2 id="分区设计" tabindex="-1">分区设计 <a class="header-anchor" href="#分区设计" aria-label="Permalink to &quot;分区设计&quot;">​</a></h2><p>下表是按当前二维底图给出的初步点位与回路建议。最终数量必须在现场确认灯具回路、窗户数量、窗帘宽度和吊顶条件后冻结。</p><table tabindex="0"><thead><tr><th>区域</th><th>灯光控制</th><th>存在与环境</th><th>窗帘与其他</th></tr></thead><tbody><tr><td>A大厅1～3</td><td>每区 2 个照明逻辑组，靠窗/内侧分别调光；每区设独立场景面板</td><td>每区 2 个存在探测点 + 1 个照度值；开放区共设 2～3 个温湿度/CO₂点</td><td>无外窗区域不装窗帘；预留清扫、午休、全开场景</td></tr><tr><td>A大厅4</td><td>2 个照明组，交流与休息模式分开</td><td>1 个存在+照度，1 个温湿度点</td><td>东侧窗帘 1 组；支持会客、遮阳、全开场景</td></tr><tr><td>B办公室1～3</td><td>每室 1～2 个照明组，门口保留实体开关</td><td>每室 1 个存在+照度；有固定人员时增加温湿度</td><td>每室东侧窗帘 1 组，共 3 组；下午防眩光</td></tr><tr><td>C办公室1～5</td><td>每室 1～2 个照明组，门口保留实体开关</td><td>每室 1 个存在+照度；有固定人员时增加温湿度</td><td>每室西侧窗帘 1 组，共 5 组；下午遮阳优先</td></tr><tr><td>D办公室1～3</td><td>房间较长，每室按前/后两组照明，避免整室同时点亮</td><td>每室 2 个存在探测点 + 1 个照度值</td><td>仅对现场确认的外窗设置窗帘，预计 0～3 组</td></tr><tr><td>D会议室</td><td>基础、会议、演示、视频四个灯光场景</td><td>1 个存在+照度，1 个 CO₂/温湿度点</td><td>西侧窗帘 1 组；与显示设备、会议预约联动</td></tr><tr><td>食堂/餐厅</td><td>灶台、食堂一、主餐厅分别控制；大餐桌上方和周边照明分组，餐厅支持调光</td><td>餐厅 2～3 个存在+照度，1～2 个 CO₂/温湿度点；灶台另设漏水和高温告警</td><td>北侧连续外窗预计 3～4 组窗帘；就餐/清洁场景</td></tr><tr><td>南侧前厅</td><td>靠入口、中央、工位外围分 3～4 组，夜间保留低照度路径灯</td><td>3～4 个存在探测点 + 2 个照度参考点</td><td>根据实际外窗决定；支持迎宾、活动、夜间和清扫场景</td></tr><tr><td>前台/接待厅</td><td>前台 2 组、接待厅 1～2 组</td><td>各 1 个存在+照度</td><td>前台南侧窗帘 1 组；访客到达联动迎宾灯</td></tr><tr><td>走廊/电梯厅/入口</td><td>分段点亮，前方区域先亮、后方区域延迟熄灭</td><td>每段 1 个存在探测点</td><td>夜间保持最低安全照明；不替代法定应急照明</td></tr><tr><td>卫生间1～3</td><td>每间 1 个照明组，风机单独延时</td><td>每间 1 个存在传感器；可增加湿度检测</td><td>无人延时关闭，风机继续运行后再停止</td></tr><tr><td>机房</td><td>照明手动优先，无人长延时关闭</td><td>温湿度、漏水、门磁和市电/UPS状态</td><td>不自动切断服务器或网络设备电源</td></tr></tbody></table><h2 id="初步设备规模" tabindex="-1">初步设备规模 <a class="header-anchor" href="#初步设备规模" aria-label="Permalink to &quot;初步设备规模&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设备类别</th><th style="text-align:right;">估算数量</th><th>说明</th></tr></thead><tbody><tr><td>照明逻辑组/可控回路</td><td style="text-align:right;">38～46</td><td>最终取决于现有配电回路和是否更换 DALI 驱动</td></tr><tr><td>自动窗帘组</td><td style="text-align:right;">15～18</td><td>以办公室、会议室、餐厅和前台外窗为主</td></tr><tr><td>存在+照度探测点</td><td style="text-align:right;">28～34</td><td>开放区和长房间需要多点覆盖，不能只按“一个房间一个”配置</td></tr><tr><td>墙面开关/场景面板</td><td style="text-align:right;">22～28</td><td>每个独立房间至少一个，开放区和餐厅分区设置</td></tr><tr><td>温湿度/CO₂点位</td><td style="text-align:right;">8～12</td><td>重点覆盖开放区、会议室、餐厅和机房</td></tr><tr><td>漏水/门磁/设备状态点</td><td style="text-align:right;">8～14</td><td>灶台、机房、入口及重要房间</td></tr><tr><td>DALI 总线</td><td style="text-align:right;">2 条</td><td>建议按南北或东西划分故障域并预留容量</td></tr><tr><td>KNX/Modbus IP 网关</td><td style="text-align:right;">1～2 台</td><td>用于窗帘、空调、计量或配电箱执行器</td></tr><tr><td>Zigbee 协调器</td><td style="text-align:right;">1 台起</td><td>配合足够的有电路由设备；覆盖不足时再拆分网络</td></tr><tr><td>本地自动化主机 + UPS</td><td style="text-align:right;">1 套</td><td>配置备份、备用存储和恢复说明必须归档</td></tr></tbody></table><p>以上是规划数量，不是采购清单。首轮采购应只覆盖试点区域，验证传感器覆盖、灯具驱动兼容性和窗帘电机噪声后再批量下单。</p><h2 id="首轮试点范围" tabindex="-1">首轮试点范围 <a class="header-anchor" href="#首轮试点范围" aria-label="Permalink to &quot;首轮试点范围&quot;">​</a></h2><p>建议用 <strong>D会议室 + A大厅1 + B办公室1 + C办公室1 + 两组不同朝向窗帘</strong> 做最小闭环，覆盖会议、开放办公、独立办公室和东/西遮阳四种典型条件。</p><table tabindex="0"><thead><tr><th>类别</th><th>试点配置</th></tr></thead><tbody><tr><td>本地平台</td><td>1 台自动化主机、1 台 UPS、MQTT 与配置备份</td></tr><tr><td>照明</td><td>6～8 个可控回路或 DALI 逻辑组，包含开关与调光两种类型</td></tr><tr><td>传感器</td><td>6～8 个存在/照度点，2～3 个温湿度/CO₂点</td></tr><tr><td>窗帘</td><td>东、西朝向各 1 组电机、控制器和本地开/停/关面板</td></tr><tr><td>人机界面</td><td>4 个墙面场景面板，1 个管理仪表盘</td></tr><tr><td>网关</td><td>1 套照明网关、1 套窗帘/Modbus或KNX接口、1 个 Zigbee 协调器</td></tr><tr><td>试运行</td><td>先记录建议动作 3～5 天，再自动执行不少于 2 周</td></tr></tbody></table><p>试点通过后再采购其余区域设备；如果出现静坐误关灯、无线丢包、窗帘定位漂移或灯具调光频闪，应先调整技术路线而不是批量复制问题。</p><h2 id="自动灯设计" tabindex="-1">自动灯设计 <a class="header-anchor" href="#自动灯设计" aria-label="Permalink to &quot;自动灯设计&quot;">​</a></h2><h3 id="控制逻辑" tabindex="-1">控制逻辑 <a class="header-anchor" href="#控制逻辑" aria-label="Permalink to &quot;控制逻辑&quot;">​</a></h3><ol><li>房间从“无人”变为“有人”时，只有实测照度低于该房间设定值才自动开灯。</li><li>靠窗灯组根据自然光单独调光，内侧灯组保持工作照度，避免全区同步开关。</li><li>离开后先进入低照度等待，再在延时结束后关闭；开放区、会议室和卫生间使用不同延时。</li><li>用户通过墙面开关手动操作后，该房间进入临时人工模式；直到人工超时、场景结束或确认无人后才恢复自动控制。</li><li>清扫、加班和活动场景必须显式启用，不能仅靠工作日时间表判断是否有人。</li></ol><h3 id="施工要求" tabindex="-1">施工要求 <a class="header-anchor" href="#施工要求" aria-label="Permalink to &quot;施工要求&quot;">​</a></h3><ul><li>每个照明回路都必须能在控制平台离线时通过墙面开关控制。</li><li>大功率或多灯具回路由接触器/合适额定值的执行器驱动，不能使用小型无线模块直接承载全部负载。</li><li>调光灯具须确认驱动协议、最低亮度、频闪和断电恢复行为。</li><li>法定应急照明、疏散指示和消防联动保持独立。</li></ul><h2 id="自动窗帘设计" tabindex="-1">自动窗帘设计 <a class="header-anchor" href="#自动窗帘设计" aria-label="Permalink to &quot;自动窗帘设计&quot;">​</a></h2><h3 id="分区原则" tabindex="-1">分区原则 <a class="header-anchor" href="#分区原则" aria-label="Permalink to &quot;分区原则&quot;">​</a></h3><ul><li>一个房间不同朝向的窗户必须分组；同朝向连续窗可在电机容量允许时合并。</li><li>B 区东侧以早间遮阳为主，C 区西侧以午后防眩光和降温为主。</li><li>餐厅和前台以整体场景为主，独立办公室允许本地覆盖自动位置。</li><li>会议室进入演示场景时关闭窗帘，会议结束后恢复到进入场景前的位置。</li></ul><h3 id="控制与安全" tabindex="-1">控制与安全 <a class="header-anchor" href="#控制与安全" aria-label="Permalink to &quot;控制与安全&quot;">​</a></h3><ul><li>电机控制器必须实现“开/关互锁”，禁止正反转同时通电。</li><li>优先选择具备位置反馈或行程反馈的电机；时间估算型电机应定期执行全开/全关校准。</li><li>人员可触及的位置优先选用遇阻停止电机；强电供电与控制回路由具备相应资质的人员施工。</li><li>墙面开、停、关按键直接接入控制器，本地操作优先于平台命令。</li><li>自动遮阳后设置人工覆盖时间，避免用户刚打开窗帘又被规则立即关闭。</li><li>窗帘供电、检修口和电机更换空间必须在吊顶施工前确认。</li></ul><h2 id="环境、空调和能耗" tabindex="-1">环境、空调和能耗 <a class="header-anchor" href="#环境、空调和能耗" aria-label="Permalink to &quot;环境、空调和能耗&quot;">​</a></h2><ul><li><strong>空气质量</strong>：会议室、开放区和餐厅根据 CO₂ 趋势联动新风或提醒开窗；阈值在试运行阶段根据人数和现场通风能力调校。</li><li><strong>空调</strong>：人员存在只影响设定温度与运行模式，不直接频繁切断空调电源；短时离开保持，长时无人进入节能设定。</li><li><strong>机房</strong>：温湿度、漏水、市电和 UPS 告警独立推送；自动化平台不得自动关闭核心设备。</li><li><strong>能耗</strong>：至少分项计量照明、普通插座、空调/新风和机房；先建立基线，再调整下班和无人策略。</li><li><strong>餐饮区</strong>：漏水、异常高温和燃气安全设备使用合规的独立报警器；平台只读取状态和通知，不取代本地声光报警或消防系统。</li></ul><h2 id="网络与安全" tabindex="-1">网络与安全 <a class="header-anchor" href="#网络与安全" aria-label="Permalink to &quot;网络与安全&quot;">​</a></h2><p>建议在现有 VLAN 10、20、99 基础上新增 <strong>VLAN 30 Automation Services</strong>：</p><table tabindex="0"><thead><tr><th>来源</th><th>目标</th><th>策略</th></tr></thead><tbody><tr><td>VLAN 10 Office/RD</td><td>VLAN 30 Home Assistant</td><td>仅开放 HTTPS 和必要管理入口</td></tr><tr><td>VLAN 30 自动化服务</td><td>VLAN 20 IoT</td><td>允许到明确设备的 MQTT、Modbus TCP、HTTPS 等必要端口</td></tr><tr><td>VLAN 20 IoT</td><td>VLAN 10 / VLAN 99</td><td>默认拒绝</td></tr><tr><td>VLAN 20 IoT</td><td>互联网</td><td>默认拒绝，仅对 DNS、NTP 和经批准的固件更新临时放行</td></tr><tr><td>VLAN 99 Management</td><td>网关与控制器</td><td>仅管理员访问，记录配置变更</td></tr></tbody></table><p>Home Assistant、MQTT、网关和协调器配置应定期备份；不得把设备密码、令牌、私钥或 KNX Secure 密钥提交到公开仓库。</p><h2 id="实施阶段" tabindex="-1">实施阶段 <a class="header-anchor" href="#实施阶段" aria-label="Permalink to &quot;实施阶段&quot;">​</a></h2><ol><li><strong>现场勘查</strong>：逐回路点灯，记录配电箱、灯具驱动、窗户尺寸、窗帘供电、空调接口和吊顶检修条件。</li><li><strong>试点</strong>：选择 D会议室、A大厅1、B办公室1、C办公室1和两组窗帘，运行不少于两周。</li><li><strong>调整</strong>：根据误关灯、传感器盲区、窗帘噪声、眩光和手动覆盖记录调整参数。</li><li><strong>分区展开</strong>：先公共区与开放区，再独立办公室，最后餐饮和能耗联动。</li><li><strong>验收移交</strong>：逐场景测试平台在线、平台离线、网络中断、断电恢复和手动覆盖。</li></ol><h2 id="方案冻结前必须确认" tabindex="-1">方案冻结前必须确认 <a class="header-anchor" href="#方案冻结前必须确认" aria-label="Permalink to &quot;方案冻结前必须确认&quot;">​</a></h2><ul><li>[ ] 每个灯光回路的负载、控制线和驱动协议。</li><li>[ ] 每扇窗的朝向、宽度、轨道形式、电机供电和检修空间。</li><li>[ ] 空调、新风和会议设备的品牌、型号与开放接口。</li><li>[ ] 吊顶材质、传感器安装高度和遮挡条件。</li><li>[ ] 哪些房间允许自动开灯，哪些只允许自动关灯。</li><li>[ ] 工作时间、午休、加班、清扫和节假日规则。</li><li>[ ] 消防、应急照明、门禁和监控的责任边界。</li></ul><h2 id="技术参考" tabindex="-1">技术参考 <a class="header-anchor" href="#技术参考" aria-label="Permalink to &quot;技术参考&quot;">​</a></h2><ul><li><a href="https://www.home-assistant.io/" target="_blank" rel="noreferrer">Home Assistant：本地控制优先的开源自动化平台</a></li><li><a href="https://www.dali-alliance.org/dali/sensors.html" target="_blank" rel="noreferrer">DALI Alliance：DALI-2 按钮、存在和照度传感器</a></li><li><a href="https://www.home-assistant.io/integrations/modbus/" target="_blank" rel="noreferrer">Home Assistant Modbus 集成</a></li><li><a href="https://www.home-assistant.io/integrations/knx/" target="_blank" rel="noreferrer">Home Assistant KNX 集成</a></li><li><a href="https://www.zigbee2mqtt.io/" target="_blank" rel="noreferrer">Zigbee2MQTT：开放的 Zigbee 到 MQTT 网桥</a></li><li><a href="https://www.home-assistant.io/integrations/matter/" target="_blank" rel="noreferrer">Home Assistant Matter 集成</a></li></ul>',41)])])}const m=d(l,[["render",o]]);export{u as __pageData,m as default};
